180	    /**
181	     * Moves the claim to the status; a change its status does not allow is refused, as is settling by the user
182	     * who opened it, and any change to a claim dated in a closed period. A clerk settling a claim whose due is above
183	     * the clerk limit makes it PENDING instead, for a steward to approve or reject.
184	     */
185	    @Transactional
186	    public Claim changeStatus(String by, String sheetId, Long id, ClaimStatus next) {
187	        Claim claim = lockedClaim(sheetId, id);
188	        switch (next) {
189	            case OPEN -> settings.refuseUnlessMay(sheetId, by, "open");
190	            case SETTLED -> settings.refuseUnlessMay(sheetId, by, "settle");
191	            case VOID -> settings.refuseUnlessMay(sheetId, by, "void");
192	            default -> {
193	            }
194	        }
195	        RollupService.Snapshot before = rollup.snapshot(sheetId);
196	        String tail = "";
197	        // settling is the step from OPEN; a pending claim is settled by approving it
198	        if (!claim.getStatus().canMoveTo(next) || next == ClaimStatus.PENDING
199	                || (next == ClaimStatus.SETTLED && claim.getStatus() != ClaimStatus.OPEN)
200	                || (next == ClaimStatus.OPEN && claim.getStatus() != ClaimStatus.DRAFT)) {
201	            throw new ResponseStatusException(HttpStatus.CONFLICT,
202	                    "A " + claim.getStatus() + " claim cannot become " + next + ".");
203	        }
204	        if (next == ClaimStatus.SETTLED && claim.isDeferredOn(sheets.load(sheetId).getToday())) {
205	            throw new ResponseStatusException(HttpStatus.CONFLICT,
206	                    "The claim is deferred until " + claim.getDeferredUntil() + ".");
207	        }
208	        if (next == ClaimStatus.SETTLED && by.equals(claim.getOpenedBy())) {
209	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The user who opened a claim cannot settle it.");
210	        }
211	        if (next == ClaimStatus.VOID && claim.getStatus() == ClaimStatus.SETTLED) {
212	            refuseVoidOfSettled(by, sheetId, claim);
213	            // the frozen figure leaves every total; the claim keeps its number and shows the figure it had
214	            tail = " reversed=" + text(claim.getSettledDue());
215	        }
216	        if (next == ClaimStatus.OPEN) {
217	            number(sheetId, claim);
218	            claim.setOpenedBy(by);
219	        }
220	        Person person = person(sheetId, claim.getPersonId());
221	        String event = switch (next) {
222	            case OPEN -> "CLAIM_OPENED";
223	            case SETTLED -> "CLAIM_SETTLED";
224	            case VOID -> "CLAIM_VOIDED";
225	            case DRAFT, PENDING -> throw new IllegalStateException();
226	        };
227	        if (next == ClaimStatus.SETTLED) {
228	            // the due is fixed at the figure a statement bound it to, else at the rate the person's grade has in
229	            // force on the claim's date, with the late charge it has gained by today, and at least the floor in force
230	            // on its date; with none it stays live
231	            BigDecimal figure = claim.isStated() && claim.getStatedDue() != null ? claim.getStatedDue()
232	                    : rateFigure(sheetId, person, claim);
233	            BigDecimal fixed = liveDue(figure, claim, sheets.load(sheetId), true);
234	            refuseWithoutProof(sheetId, claim, fixed);
235	            if (settings.aboveClerkLimit(sheetId, by, fixed)) {
236	                next = ClaimStatus.PENDING;
237	                event = "CLAIM_PENDING";
238	            } else {
239	                claim.setSettledDue(fixed);
240	                tail = " due=" + (fixed == null ? "n/a" : fixed.toPlainString());
241	            }
242	        }
243	        claim.setStatus(next);
244	        logStatus(by, sheetId, person, claim);
245	        Claim saved = claims.saveAndFlush(claim);
246	        audit.recordOnCommit(record(event, by, person, saved) + tail);
247	        if (next == ClaimStatus.SETTLED) {
248	            watches.notifyWatchers(by, sheetId, person, saved.getNumber());
249	        }
250	        rollup.recordChanges(by, sheetId, before);
251	        return saved;
252	    }
