455	    /**
456	     * Splits an amount (more than 0.00 and less than the claim's) off an OPEN claim: the claim keeps the rest and
457	     * loses any figure a statement bound it to; a new OPEN claim with the amount, the same date and note, the next
458	     * number, opened by the user, with a due-by from the terms in force on the date, and split from the original's
459	     * number, is listed as its person's newest. Refused unless the user's role may open a claim, for a claim that is
460	     * not OPEN or is deferred, for an amount out of range, and in a closed period.
461	     */
462	    @Transactional
463	    public Split split(String by, String sheetId, Long id, BigDecimal amount) {
464	        settings.refuseUnlessMay(sheetId, by, "open");
465	        Claim claim = lockedClaim(sheetId, id);
466	        if (claim.getStatus() != ClaimStatus.OPEN) {
467	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only an OPEN claim can be split.");
468	        }
469	        if (claim.isDeferredOn(sheets.load(sheetId).getToday())) {
470	            throw new ResponseStatusException(HttpStatus.CONFLICT,
471	                    "The claim is deferred until " + claim.getDeferredUntil() + ".");
472	        }
473	        if (amount == null || amount.signum() <= 0 || amount.compareTo(claim.getAmount()) >= 0) {
474	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
475	                    "The amount split off must be more than 0.00 and less than the claim's.");
476	        }
477	        RollupService.Snapshot before = rollup.snapshot(sheetId);
478	        Person person = person(sheetId, claim.getPersonId());
479	        claim.setAmount(claim.getAmount().subtract(scaled(amount)));
480	        claim.unbind();
481	        Claim original = claims.saveAndFlush(claim);
482	        Claim part = new Claim(sheetId, claim.getPersonId(), scaled(amount), claim.getDate(), claim.getNote());
483	        part.setRoundsOn(claim.getRoundsOn());
484	        part.setDueBy(claim.getDate().plusDays(termsFor(sheetId, person, claim.getDate())));
485	        part.setSplitFrom(claim.getNumber());
486	        part.setStatus(ClaimStatus.OPEN);
487	        number(sheetId, part);
488	        part.setOpenedBy(by);
489	        logStatus(by, sheetId, person, part);
490	        Claim added = claims.saveAndFlush(part);
491	        audit.recordOnCommit(record("CLAIM_SPLIT", by, person, original) + " into=" + added.getNumber());
492	        audit.recordOnCommit(record("CLAIM_OPENED", by, person, added));
493	        rollup.recordChanges(by, sheetId, before);
494	        return new Split(original, added);
495	    }
496	
497	    /**
498	     * Refuses voiding a SETTLED claim unless the user is a steward and the sheet's today is within
499	     * {@link #VOID_SETTLED_DAYS} days of the date its status log records it settled.
500	     */
501	    private void refuseVoidOfSettled(String by, String sheetId, Claim claim) {
502	        if (!settings.isSteward(sheetId, by)) {
503	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can void a settled claim.");
504	        }
505	        LocalDate settledOn = claim.settledOn();
506	        LocalDate today = sheets.load(sheetId).getToday();
507	        if (settledOn == null || today == null || today.isBefore(settledOn)
508	                || ChronoUnit.DAYS.between(settledOn, today) > VOID_SETTLED_DAYS) {
509	            throw new ResponseStatusException(HttpStatus.CONFLICT,
510	                    "A settled claim can only be voided within " + VOID_SETTLED_DAYS + " days of its settlement.");
511	        }
512	    }
513	
514	    /** Logs the status the claim now has: by the user, on the sheet's today, at the due it shows now. */
515	    private void logStatus(String by, String sheetId, Person person, Claim claim) {
516	        claim.logStatus(by, sheets.load(sheetId).getToday(), due(sheetId, person, claim));
517	    }
518	
519	    /** The pending claim, locked, for a steward to decide; refused otherwise. */
520	    private Claim pendingClaim(String by, String sheetId, Long id) {
521	        Claim claim = lockedClaim(sheetId, id);
522	        if (claim.getStatus() != ClaimStatus.PENDING) {
523	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only a PENDING claim can be approved or rejected.");
524	        }
525	        if (!settings.isSteward(sheetId, by)) {
526	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can approve or reject a claim.");
527	        }
528	        return claim;
529	    }
530	
531	    /** The claim, locked; refused when it is dated in a closed period. */
532	    private Claim lockedClaim(String sheetId, Long id) {
533	        // the sheet is locked before the claim, in the order a period closing takes them
534	        sheets.lock(sheetId);
535	        Claim claim = claims.findWithLockByIdAndSheetId(id, sheetId)
536	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
537	        refuseInClosedPeriod(sheetId, claim.getDate());
538	        return claim;
539	    }
540	
541	    /**
542	     * Gives the claim being opened its number: while the sheet's period numbering from is set and its today is on or
543	     * after it, the next in the sequence of the period the claim is dated in (X for none), else the sheet's next.
544	     * The sheet is locked, so two claims opened at once never get the same one.
545	     */
546	    private void number(String sheetId, Claim claim) {
547	        if (!numbersByPeriod(sheetId)) {
548	            claim.setNumber(String.valueOf(sheets.nextClaimNumber(sheetId)));
549	            return;
550	        }
551	        String sequence = sequenceOn(sheetId, claim.getDate());
552	        Long last = claims.lastInSequence(sheetId, sequence);
553	        claim.numberIn(sequence, last == null ? 1 : last + 1);
554	    }
555	
556	    /** Whether the sheet numbers claims by period: its period numbering from is set and its today on or after it. */
557	    private boolean numbersByPeriod(String sheetId) {
558	        Sheet sheet = sheets.load(sheetId);
559	        LocalDate from = sheet.getPeriodNumberingFrom();
560	        return from != null && !sheet.getToday().isBefore(from);
561	    }
562	
563	    /** The number sequence of a claim dated on the date: the name of the period it is in, or X for none. */
564	    private String sequenceOn(String sheetId, LocalDate date) {
565	        return periods.findFirstBySheetIdAndFromLessThanEqualAndToGreaterThanEqual(sheetId, date, date)
566	                .map(Period::getName).orElse(NO_PERIOD);
567	    }
568	
569	    /**
570	     * The claim's rate figure: at the rate its person's grade in force on its date has in force on that date, rounded
571	     * as the sheet's policy date decides for it, with no floor; null (n/a) with none.
572	     */
573	    public BigDecimal rateFigure(String sheetId, Person person, Claim claim) {
574	        Sheet sheet = sheets.load(sheetId);
575	        RoundingMode rounding = sheet.roundingOn(claim.getRoundsOn());
576	        return rates.findInForce(sheetId, person.gradeOn(claim.getDate()), claim.getDate()).map(Rate::getPct)
577	                .map(pct -> dueOn(claim.getAmount(), pct, rounding)).orElse(null);
578	    }
579	
580	    /**
581	     * The figure of the claim: its settled due, else the one a statement bound it to (not while it is pending), else
582	     * its rate figure. A statement binds this figure, under the late charge and the floor.
583	     */
584	    public BigDecimal figure(String sheetId, Person person, Claim claim) {
585	        if (claim.getSettledDue() != null) {
586	            return claim.getSettledDue();
587	        }
588	        return claim.isBound() ? claim.getStatedDue() : rateFigure(sheetId, person, claim);
589	    }
590	
591	    /**
592	     * The due the claim shows and totals: its settled due as frozen, else its live due on its figure (the late charge
593	     * only while it is open or pending).
594	     */
595	    public BigDecimal due(String sheetId, Person person, Claim claim) {
596	        BigDecimal figure = figure(sheetId, person, claim);
597	        return claim.getSettledDue() != null ? figure
598	                : liveDue(figure, claim, sheets.load(sheetId), claim.getStatus().isOpen());
599	    }
600	
601	    /**
602	     * The live due of a claim on its (unfloored) figure: the greater of the floor in force on its date and the figure
603	     * plus the late charge it has gained (when charged); a correction has neither floor nor charge. Null (n/a) for an
604	     * n/a figure.
605	     */
606	    public static BigDecimal liveDue(BigDecimal figure, Claim claim, Sheet sheet, boolean charged) {
607	        if (figure == null || claim.isCorrection()) {
608	            return figure;
609	        }
610	        BigDecimal due = charged ? withLateCharge(figure, claim, sheet) : figure;
611	        return sheet == null ? due : floored(due, sheet.floorOn(claim.getDate()));
612	    }
613	
614	    /**
615	     * The figure (null for n/a) of the claim, with a late charge added for every full 30 days it is overdue (past its
616	     * due-by) by the sheet's today: for each such boundary (its due-by plus 30, 60, 90 ... days), the sheet's late
617	     * percent in force on that boundary date of the figure, rounded like its due; a boundary whose percent is 0.00
618	     * adds nothing. A deferred claim is not overdue. The charge is never bound by a statement: it keeps following the
619	     * sheet's today and its policy date.
620	     */
621	    public static BigDecimal withLateCharge(BigDecimal figure, Claim claim, Sheet sheet) {
622	        if (figure == null || sheet == null || sheet.getToday() == null || claim.isDeferredOn(sheet.getToday())) {
623	            return figure;
624	        }
625	        long overdue = ChronoUnit.DAYS.between(claim.getDueBy(), sheet.getToday());
626	        long periods = overdue > 0 ? overdue / 30 : 0;
627	        RoundingMode rounding = sheet.roundingOn(claim.getRoundsOn());
628	        BigDecimal due = figure;
629	        for (long k = 1; k <= periods; k++) {
630	            BigDecimal latePct = sheet.latePctOn(claim.getDueBy().plusDays(30 * k));
631	            if (latePct.signum() != 0) {
632	                due = due.add(dueOn(figure, latePct, rounding));
633	            }
634	        }
635	        return due;
636	    }
637	
638	    /**
639	     * Refuses a change to a claim dated on the date when a closed period contains it. The sheet stays locked until
640	     * the transaction ends, so a period closing at the same moment is checked in turn.
641	     */
642	    private void refuseInClosedPeriod(String sheetId, LocalDate date) {
643	        sheets.lock(sheetId);
644	        if (periods.existsBySheetIdAndClosedTrueAndFromLessThanEqualAndToGreaterThanEqual(sheetId, date, date)) {
645	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That claim is dated in a closed period.");
646	        }
647	    }
648	
649	    /**
650	     * The number a claim with the amount corrects: for a correction (a negative amount), the number of a settled
651	     * claim of the person, else refused; null for any other claim.
652	     */
653	    private String correctedNumber(String sheetId, Long personId, BigDecimal amount, String corrects) {
654	        if (amount.signum() >= 0) {
655	            return null;
656	        }
657	        corrects = corrects == null ? null : corrects.strip();
658	        if (corrects == null || !claims.existsBySheetIdAndPersonIdAndNumberAndStatus(sheetId, personId, corrects,
659	                ClaimStatus.SETTLED)) {
660	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
661	                    "A negative amount must correct a settled claim of the person, named by its number.");
662	        }
663	        return corrects;
664	    }
665	
666	    /** Refuses a claim for the person dated after their retirement date; one on or before it is allowed. */
667	    private static void refuseAfterRetirement(Person person, LocalDate date) {
668	        if (person.getRetiredFrom() != null && date.isAfter(person.getRetiredFrom())) {
669	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
670	                    "That claim is dated after the person's retirement.");
671	        }
672	    }
673	
674	    private Person person(String sheetId, Long personId) {
675	        return people.findByIdAndSheetId(personId, sheetId)
676	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
677	    }
678	
679	    /**
680	     * The terms a claim of the person dated on the date has: the person's own, else those of their grade on the date,
681	     * else the sheet's on the date.
682	     */
683	    private int termsFor(String sheetId, Person person, LocalDate on) {
684	        return person.getTerms() != null ? person.getTerms()
685	                : sheets.load(sheetId).termsFor(person.gradeOn(on), on);
686	    }
687	
688	    /** The audit line about a claim; one that has a number ends with it. */
689	    private static String record(String event, String by, Person person, Claim c) {
690	        String number = c.getNumber();
691	        return event + " sheet=" + c.getSheetId() + " by=" + by + " person=" + person.getName()
692	                + " amount=" + c.getAmount().toPlainString() + " date=" + c.getDate()
693	                + (number != null ? " number=" + number : "");
694	    }
695	
696	    /**
697	     * The due on an amount at a rate: amount times rate divided by 100, rounded to two decimals the given way (a
698	     * negative amount rounds like its positive).
699	     */
700	    public static BigDecimal dueOn(BigDecimal amount, BigDecimal pct, RoundingMode rounding) {
701	        return amount.multiply(pct).movePointLeft(2).setScale(2, rounding);
702	    }
703	
704	    /** The date a claim dated on the date rounds by: that date, or for a correction the corrected claim's date. */
705	    private LocalDate roundsOn(String sheetId, String corrects, LocalDate on) {
706	        return corrects == null ? on
707	                : claims.findBySheetIdAndNumber(sheetId, corrects).map(Claim::getDate).orElse(on);
708	    }
709	
710	    /** The due raised to the floor when it is below it. */
711	    public static BigDecimal floored(BigDecimal due, BigDecimal floor) {
712	        return floor != null && due.compareTo(floor) < 0 ? floor.setScale(2) : due;
713	    }
714	
715	    private LocalDate dateOrToday(String sheetId, LocalDate date) {
716	        return date != null ? date : sheets.load(sheetId).getToday();
717	    }
718	
719	    private static String text(BigDecimal value) {
720	        return value == null ? "n/a" : value.toPlainString();
721	    }
722	
723	    private static BigDecimal scaled(BigDecimal amount) {
724	        return amount.setScale(2, RoundingMode.UNNECESSARY);
725	    }
726	
727	    private static String noteOf(String note) {
728	        return note == null ? "" : note.strip();
729	    }
730	}
