                .max(Comparator.comparing(Rate::getFrom,
                        Comparator.nullsFirst(Comparator.naturalOrder())))
                .orElse(null);
        return best == null || (best.getTo() != null && best.getTo().isBefore(date)) ? null : best;
    }
}
